def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')

    if n < 5:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    recent_n = 10 if n >= 10 else n
    recent = opp[-recent_n:]
    r_d = recent.count('D')
    r_c = recent_n - r_d
    recent_rate = r_c / recent_n
    overall_rate = opp_c / n

    if n >= 92:
        if overall_rate >= 0.75:
            return 'D'
        return 'D' if recent_rate < 0.5 else 'C'

    if n >= 80:
        if overall_rate >= 0.8:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'C' if recent_rate >= 0.5 else 'D'

    if r_d >= recent_n - 1 and n >= 12:
        if overall_rate <= 0.25:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if r_c >= recent_n - 1:
        if overall_rate >= 0.9 and n >= 20:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    if overall_rate >= 0.85:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        if last_opp == 'D' and last_me == 'D':
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'C'

    if overall_rate <= 0.25:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 4:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    if overall_rate >= 0.65:
        return 'C'

    if rng.random() < 0.55:
        return 'C'
    return 'D'
